mapper.select:
select top 1 id, mobile, email, purpose, code_salt, code_hash, state, expire_time, wrong_times,
       send_time, send_ip, send_ua, verify_time, verify_ip, fail_reason,
       modedatacreater, modedatacreatedate, modedatacreatetime,
       modedatamodifier, modedatamodifydatetime
from ${table}
where 1 = 1

    and mobile = #{mobile}


    and email = #{email}


    and purpose = #{purpose}

order by id desc

select count(1) from ${table}
where 1 = 1

    and mobile = #{mobile}


    and email = #{email}

and send_time >= #{since}

    and purpose = #{purpose}

mapper.update:
update ${table}
set wrong_times = #{wrongTimes},
    fail_reason = #{failReason}
where id = #{id}

update ${table}
set state = 1,
    verify_time = #{verifyTime},
    verify_ip = #{verifyIp},
    fail_reason = null
where id = #{id}

update ${table}
set state = 2,
    fail_reason = #{failReason}
where id = #{id}

mapper.delete:
delete from ${table}
where (expire_time is not null and expire_time < #{before})
   or (send_time is not null and send_time < #{before})
